"The Hours of Our Lady, from Matins to Compline, following the seasons of the year. A beloved prayer of religious, tertiaries, and those who wear the Brown Scapular.": "Часы Пресвятой Девы, от Утрени до Повечерия, по временам года. Любимая молитва монашествующих, терциариев и носящих коричневый скапулярий.",
"The Brown and Green Scapulars, the Miraculous and St. Benedict Medals, First Fridays and First Saturdays, and holy water: what each one is, how to keep it, and its prayers.": "Коричневый и зелёный скапулярии, Чудотворный медальон и медальон святого Бенедикта, первые пятницы и первые субботы, святая вода: что это, как это хранить и молитвы.",
"The ancient prayer of the Incarnation, prayed at morning, noon, and evening. During the Easter season, the Regina Caeli.": "Древняя молитва о Воплощении, читаемая утром, в полдень и вечером. В пасхальное время — Regina Caeli.",
"Pray with a passage of Scripture the way the monks did: read, reflect, respond, and rest in God.": "Молитесь отрывком Писания, как монахи: читайте, размышляйте, отвечайте и отдыхайте в Боге.",
"Keep a private record of your daily prayer, build a steady habit, and see your faithfulness over the weeks.": "Ведите личный дневник ежедневной молитвы, вырабатывайте привычку и смотрите на свою верность неделя за неделей.",
"Every part of the Mass in order, with when to stand, sit, and kneel, and what each moment means. Follow along on your phone at Mass.": "Каждая часть мессы по порядку: когда стоять, сидеть и стоять на коленях, и что означает каждый момент. Следите по телефону во время мессы.",
"Every pope from St. Peter to Leo XIV, century by century.": "Все папы от святого Петра до Льва XIV, век за веком.",
"The great religious orders of the Church: monks, canons, friars, clerks regular, sisters, and the military orders of the crusades.": "Великие ордены Церкви: монахи, каноники, нищенствующие братья, регулярные клирики, сёстры и рыцарские ордены крестовых походов.",
"The most famous icons of East and West, what they show, and the stories behind them.": "Самые знаменитые иконы Востока и Запада: что они изображают и их истории.",
"The twenty-three Eastern Catholic Churches, in full communion with Rome: their traditions, leaders, and lands.": "Двадцать три Восточные католические Церкви в полном общении с Римом: их традиции, предстоятели и земли.",
"How to become Catholic or come home, the basics of everyday Catholic life, and guides to discerning and living each vocation: marriage, priesthood, religious life, and more.": "Как стать католиком или вернуться в Церковь, основы повседневной католической жизни и руководства по распознаванию и проживанию каждого призвания: брак, священство, монашество и другие.",
"The lists every Catholic learns, explained: the Ten Commandments, the Beatitudes, the precepts, the sacraments, the virtues, the works of mercy, the capital sins, and more.": "Перечни, которые узнаёт каждый католик, с объяснениями: Десять заповедей, Заповеди блаженства, церковные заповеди, таинства, добродетели, дела милосердия, смертные грехи и другие.",
"A walk through a Catholic church: what each part is for, the sacred vessels, the vestments, the colors of the seasons, and how to take part in the Mass.": "Прогулка по католическому храму: для чего каждая его часть, священные сосуды, облачения, цвета литургических периодов и как участвовать в мессе.",
"All twenty-one ecumenical councils, from Nicaea to Vatican II: when and where they met, and what each one taught.": "Все двадцать один Вселенский собор, от Никейского до II Ватиканского: когда и где они проходили и чему учил каждый.",
"Clear, short definitions of the words of the Catholic faith, from Absolution to the Vulgate.": "Короткие и ясные определения слов католической веры, от «отпущения» до «Вульгаты».",
"The words of the saints, from the Church Fathers to our own day, each with its source. Search them, browse by theme, and share your favorites.": "Слова святых, от Отцов Церкви до наших дней, каждое с источником. Ищите, просматривайте по темам и делитесь любимыми.",
"Pick as many answers as you like: your name, your work, your needs, and what you love in a saint. Sanctify suggests friends in heaven who fit.": "Выберите сколько угодно ответов: ваше имя, работу, нужды и то, что вам дорого в святых. Sanctify предложит друзей на небесах, которые вам подходят.",
"Trusted places to keep learning about the faith: Church documents, Scripture and prayer, podcasts, video, courses, and more.": "Надёжные места, чтобы дальше изучать веру: церковные документы, Писание и молитва, подкасты, видео, курсы и другое.",
"Share prayer requests, ask questions about the faith, and talk about the saints and good books with other Sanctify members.": "Делитесь просьбами о молитве, задавайте вопросы о вере и говорите о святых и хороших книгах с другими участниками Sanctify.",
