"Pray with the whole Church: the prayers of the saints, the Rosary, the Way of the Cross, and quiet time alone with God.": "Молитесь со всей Церковью: молитвы святых, Розарий, Крестный путь и тихое время наедине с Богом.",
"Where to begin": "С чего начать",
"Pray the Rosary bead by bead, with a meditation for each mystery. The mysteries change with the day of the week.": "Молитесь Розарием бусина за бусиной, с размышлением над каждой тайной. Тайны меняются по дням недели.",
"About {n} minutes": "Около {n} минут",
"Begin praying →": "Начать молитву →",
"Every prayer as an illustrated card, from the Sign of the Cross to the Te Deum, some in Latin and Spanish.": "Каждая молитва — иллюстрированная карточка, от крестного знамения до Te Deum, некоторые на латыни и испанском.",
"{n} prayer cards": "{n} молитвенных карточек",
"Open →": "Открыть →",
"Walk the fourteen Stations with Christ, with a short meditation at each.": "Пройдите четырнадцать стояний вместе с Христом, с кратким размышлением на каждом.",
"{n} stations": "{n} стояний",
"The Chaplet of Divine Mercy, as given to St. Faustina, prayed on rosary beads.": "Венчик Божьего Милосердия, данный святой Фаустине, читаемый на чётках.",
"Thirty-three beads for the years of Christ’s life: “Sweet Heart of Jesus, be my love.”": "Тридцать три бусины по годам жизни Христа: «Сладчайшее Сердце Иисуса, будь моей любовью».",
"Prepare for Confession with a guided examination, following the Ten Commandments.": "Подготовьтесь к исповеди с пошаговым испытанием совести по Десяти заповедям.",
"Private: nothing is saved": "Лично: ничего не сохраняется",
"Set aside time for silent prayer or a Holy Hour, with a gentle bell to begin and end.": "Выделите время для безмолвной молитвы или святого часа, с тихим колокольчиком в начале и в конце.",
"{n} minutes to an hour": "От {n} минут до часа",
"Look back on your day with God in five short steps, the evening prayer of St. Ignatius.": "Оглянитесь на свой день вместе с Богом в пять коротких шагов — вечерняя молитва святого Игнатия.",
"Pause at morning, noon, or evening to honor the Incarnation with Mary.": "Остановитесь утром, в полдень или вечером, чтобы с Марией почтить Воплощение.",
"Pray slowly with a passage of Scripture: read, reflect, respond, and rest.": "Медленно молитесь отрывком Писания: читайте, размышляйте, отвечайте и отдыхайте.",
"Gregorian chant and beloved hymns to listen to and sing, with the words in Latin and English.": "Григорианский хорал и любимые гимны, чтобы слушать и петь, с текстами на латыни и английском.",
"Recordings and words": "Записи и тексты",
"The Hours of Our Lady: psalms, hymns, and readings in honor of Mary, from Matins to Compline, following the seasons.": "Часы Пресвятой Девы: псалмы, гимны и чтения в честь Марии, от Утрени до Повечерия, по временам года.",
"{n} Hours": "{n} часов",
"The Brown and Green Scapulars, the Miraculous and St. Benedict Medals, First Fridays and Saturdays, and holy water, with their prayers.": "Коричневый и зелёный скапулярии, Чудотворный медальон и медальон святого Бенедикта, первые пятницы и субботы и святая вода — с молитвами.",
"{n} devotions": "{n} практик",
"A private record of your daily prayer, with streaks and a calendar of your faithfulness.": "Личный дневник ежедневной молитвы с сериями и календарём вашей верности.",
"Stored only on this device": "Хранится только на этом устройстве",
"Novenas & Intentions": "Новенны и намерения",
"Keep a list of your prayer intentions, and pray a nine-day novena with any saint.": "Ведите список молитвенных намерений и совершайте девятидневную новенну с любым святым.",
"Read and explore": "Читать и открывать",
"All 73 books of the Catholic Bible, the Catechism, the books that formed the saints, plans for reading Scripture, and trusted places to go deeper.": "Все 73 книги католической Библии, Катехизис, книги, сформировавшие святых, планы чтения Писания и надёжные места для углубления.",
"The Word of God": "Слово Божие",
"Read all 73 books of the Catholic canon right here in the Douay-Rheims, chapter by chapter, with Bishop Challoner’s notes.": "Читайте здесь все 73 книги католического канона в переводе Douay-Rheims (по-английски), глава за главой, с примечаниями епископа Челлонера.",
"{n} books": "{n} книг",
"Open the Bible →": "Открыть Библию →",
"Spiritual classics, the Church Fathers, Church documents, and great Catholic literature, with summaries and links to read.": "Духовная классика, Отцы Церкви, церковные документы и великая католическая литература, с кратким содержанием и ссылками.",
"The whole Catechism of the Catholic Church, part by part, with any paragraph a tap away, and older catechisms to read in full right here.": "Весь Катехизис Католической Церкви, часть за частью, любой пункт в одно касание, и старые катехизисы для полного чтения прямо здесь.",
"{n} paragraphs": "{n} пунктов",
"Read the Gospels in 30 days, the New Testament in 90, or the whole Bible in a year.": "Прочитайте Евангелия за 30 дней, Новый Завет за 90 или всю Библию за год.",
"{n} plans": "{n} планов",
"Trusted websites, podcasts, videos, and courses for going deeper in the faith.": "Надёжные сайты, подкасты, видео и курсы для углубления в вере.",
"{n} resources": "{n} материалов",
"Reputable shops for icons, rosaries, books, and other Catholic goods.": "Надёжные магазины икон, чёток, книг и других католических товаров.",
"Trusted shops": "Надёжные магазины",
"Every prayer, saint, book, event, and teaching in one searchable list.": "Все молитвы, святые, книги, события и учения в одном списке с поиском.",
