"Surprise me →": "Удиви меня →",
"Study the faith": "Изучать веру",
"What the Church believes and why: her teaching, her worship, and the words of the faith.": "Во что верит Церковь и почему: её учение, богослужение и слова веры.",
"Doctrine & apologetics": "Вероучение и апологетика",
