"Start learning →": "Начать изучение →",
"Every part of the Mass, with when to stand, sit, and kneel and what each moment means, and a guide to the Traditional Latin Mass. Follow along on your phone.": "Каждая часть мессы — когда стоять, сидеть и стоять на коленях, что означает каждый момент — и руководство по традиционной латинской мессе. Следите по телефону.",
"The Order of Mass": "Чин мессы",
"Becoming Catholic, coming home, the precepts of the Church, and guides to discerning and living every vocation.": "Стать католиком, вернуться в Церковь, церковные заповеди и руководства по распознаванию и проживанию каждого призвания.",
"{n} guides": "{n} руководств",
"The Commandments, the Beatitudes, the precepts, the sacraments, the virtues, the works of mercy, the capital sins, and more, each explained.": "Заповеди, Заповеди блаженства, церковные заповеди, таинства, добродетели, дела милосердия, смертные грехи и другое — с объяснениями.",
"{n} lists": "{n} перечней",
"The altar, the tabernacle, the sacred vessels, the vestments, the colors of the seasons, and how to take part in Mass.": "Алтарь, дарохранительница, священные сосуды, облачения, цвета литургических периодов и как участвовать в мессе.",
