"From Pentecost to today": "От Пятидесятницы до наших дней",
"Two thousand years on one timeline: councils, schisms, missions, martyrs, and the apparitions of Our Lady, each with the story behind it.": "Две тысячи лет на одной ленте времени: соборы, расколы, миссии, мученики и явления Богородицы, каждое со своей историей.",
