"All twenty-one ecumenical councils, from Nicaea in 325 to Vatican II: where they met and what they taught.": "Все двадцать один Вселенский собор, от Никейского 325 года до II Ватиканского: где они проходили и чему учили.",
"{n} councils": "{n} соборов",
"The great icons of East and West, from the Sinai Pantocrator to Rublev’s Trinity, and what to look for in each.": "Великие иконы Востока и Запада, от Синайского Пантократора до «Троицы» Рублёва, и на что смотреть в каждой.",
