"{n} orders": "{n} орденов",
"The twenty-three Eastern Catholic Churches in communion with Rome: Byzantine, Syriac, Chaldean, Armenian, and Alexandrian.": "Двадцать три Восточные католические Церкви в общении с Римом: византийские, сирийские, халдейская, армянская и александрийские.",
