"Keep a list of the people and needs you are praying for. When a prayer is answered, mark it and give thanks.": "Ведите список людей и нужд, за которые вы молитесь. Когда молитва услышана, отметьте это и возблагодарите.",
"Tap ☆ Save on any prayer, saint, book, or article to keep it here.": "Нажмите ☆ Сохранить на любой молитве, святом, книге или статье, чтобы держать их здесь.",
