"Announcements from the Sanctify team will appear here soon.": "Скоро здесь появятся объявления команды Sanctify.",
"to show them on a public profile and earn Community badges.": "чтобы показывать их в публичном профиле и получать значки сообщества.",
"Prayer badges count the days you mark in your prayer tracker; finishing a Rosary, chaplet, or other guided prayer marks it for you.": "Молитвенные значки считают дни, отмеченные в вашем молитвенном дневнике; завершённый Розарий, венчик или другая молитва с подсказками отмечаются сами.",
"From Church History": "Из истории Церкви",
