"Know Your Faith": "Знай свою веру",
"Erase your saved entries, novenas, intentions, prayer record, badges, and settings from this device? This can’t be undone. You may want to download a backup first.": "Стереть с этого устройства сохранённые записи, новенны, намерения, молитвенный дневник, значки и настройки? Это нельзя отменить. Возможно, сначала стоит скачать резервную копию.",
"Replace what’s on this device with the backup from {*}?": "Заменить данные на этом устройстве резервной копией от {*}?",
"follows the Roman Missal of 1962 and its calendar: the old feasts and seasons, Ember Days, the Latin Mass explained, and the fifteen mysteries of the Rosary. Its prayers are those of the Roman Catholic edition.": "следует Римскому миссалу 1962 года и его календарю: старые праздники и периоды, дни четырёх времён года, объяснение латинской мессы и пятнадцать тайн Розария. Молитвы в нём те же, что в римско-католическом издании.",
