"Pray the Rosary bead by bead with the fifteen traditional mysteries, Joyful, Sorrowful, and Glorious, and a meditation for each.": "Молитесь Розарием бусина за бусиной с пятнадцатью традиционными тайнами — радостными, скорбными и славными — и размышлением над каждой.",
