"follows the Byzantine tradition, shared by the Ukrainian, Ruthenian, Melkite, Romanian, and other Greek Catholic Churches. The Maronite, Syro-Malabar, Chaldean, Armenian, Coptic, and other Eastern Catholic Churches have their own liturgies.": "следует византийской традиции, общей для Украинской, Русинской, Мелькитской, Румынской и других грекокатолических Церквей. Маронитская, Сиро-Малабарская, Халдейская, Армянская, Коптская и другие Восточные католические Церкви имеют свои литургии.",
"Eastern Catholic edition": "Восточнокатолическое издание",
