"The great Lenten prayer of St. Ephrem the Syrian, prayed with prostrations on the weekdays of Great Lent.": "Великая великопостная молитва святого Ефрема Сирина, читаемая с земными поклонами в будни Великого поста.",
"Close the day with God in stillness, thanksgiving, watchfulness, and repentance.": "Завершите день с Богом в тишине, благодарении, трезвении и покаянии.",
