"Akathist & Paraklesis": "Акафист и Параклис",
"Akathist": "Акафист",
"The whole Akathist Hymn to the Theotokos, sung standing, and the Paraklesis of supplication.": "Полный Акафист Богородице, который поют стоя, и молебный Параклис.",
